add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/ps', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { $out = array(); foreach ( get_posts( array( 'post_type' => 'nadlan_project', 'post_status' => 'publish', 'posts_per_page' => 30 ) ) as $p ) { $out[] = array( 'slug' => $p->post_name, 'status' => get_post_meta( $p->ID, 'project_status', true ), 'ms' => (bool) get_post_meta( $p->ID, 'project_milestones_json', true ), 'delivery' => get_post_meta( $p->ID, 'delivery_date', true ) ); } return $out; } ) ); } );